const PATTERN_ALIASES = {'two-pointers':'sorted-two-sum'};
// Apply once: a reviewed combined card transfers to both of its new parts.
const REVIEW_MIGRATIONS = {
 'two-pointers':['sorted-two-sum'],
 'fast-slow':['fast-slow','cycle-detection'],
 'quicksort':['quicksort','two-way-partition'],
 'inorder':['inorder','kth-inorder']
};
function migrateReviewed(saved) {
 if(!Array.isArray(saved)) return [];
 return [...new Set(saved.flatMap(id=>REVIEW_MIGRATIONS[id]||[id]))].filter(id=>PATTERNS.some(p=>p.id===id));
}

